export const collectMatchingIndexedLoadMorePage = async ({
  requestedLimit = 1,
  initialOffset = 0,
  maxPages = 5,
  baseExclude = [],
  loadedIds = new Set(),
  filters = {},
  viewMode = 'default',
  ownerId = '',
  viewerRole = '',
  viewerId = ownerId,
  fetchMatchingIndexedCandidates,
  hydrateUsersByIds,
  isLatestLoadMore = () => true,
} = {}) => {
  const collected = [];
  const collectedIds = new Set();
  let offset = Number(initialOffset) || 0;
  let finalOffset = offset;
  let finalHasMore = false;
  let cursorStuck = false;
  let pageCalls = 0;
  let budgetedPageCalls = 0;
  let stopReason = '';
  let usedIndex = false;
  let deferReason = '';
  let indexedIdsCount = 0;
  let paginationInputIdsCount = 0;
  let pageIdsCount = 0;
  let fetchedCardsCount = 0;
  let safetyFilteredOutCount = 0;
  // Keep continuation reads finite while still letting sparse index windows
  // advance without consuming the smaller UI page budget.
  const maxPageCalls = maxPages * 2;

  while (
    collected.length < requestedLimit
    && budgetedPageCalls < maxPages
    && pageCalls < maxPageCalls
  ) {
    pageCalls += 1;
    if (typeof window !== 'undefined' && window.matchingLoadStats) {
      window.matchingLoadStats.backfillPages = (Number(window.matchingLoadStats.backfillPages) || 0) + 1;
    }
    const collectedUserIds = collected.map(user => user?.userId).filter(Boolean);
    const excludeIds = new Set([
      ...baseExclude,
      ...loadedIds,
      ...collectedUserIds,
    ]);
    const indexed = await fetchMatchingIndexedCandidates({
      filters,
      viewMode,
      ownerId,
      viewerRole,
      viewerId,
      offset,
      limit: requestedLimit - collected.length,
      excludeIds: [...excludeIds],
      hydrateUsersByIds,
    });
    if (!isLatestLoadMore()) {
      return {
        collected,
        finalOffset,
        finalHasMore,
        cursorStuck,
        pageCalls,
        stale: true,
        usedIndex,
        deferToSourcePagination: false,
        deferReason,
        staleReason: 'loadMore-stale-or-filter-changed',
      };
    }

    // План може не скластись зовсім: коли кожна група індексу вміє лише
    // відкидати (усі «крім …»), провайдер не називає жодного id і віддає деку
    // послідовній пагінації. Для читача це не «нічого не знайшлось» — це
    // «питати треба інакше», і тому це має бути видно тому, хто викликав.
    if (indexed.usedIndex === false) deferReason = indexed.reason || 'index-plan-unavailable';
    else usedIndex = true;

    indexedIdsCount += Array.isArray(indexed.userIds) ? indexed.userIds.length : 0;
    paginationInputIdsCount += Array.isArray(indexed.paginationInputIds) ? indexed.paginationInputIds.length : 0;
    pageIdsCount += Array.isArray(indexed.pageIds) ? indexed.pageIds.length : 0;
    fetchedCardsCount += Array.isArray(indexed.users) ? indexed.users.length : 0;

    const indexedUsers = (indexed.users || []).filter(
      user => user?.userId && !loadedIds.has(user.userId) && !collectedIds.has(user.userId)
    );
    safetyFilteredOutCount += Math.max(0, (Array.isArray(indexed.users) ? indexed.users.length : 0) - indexedUsers.length);
    indexedUsers.forEach(user => {
      collected.push(user);
      collectedIds.add(user.userId);
    });

    const nextOffset = Number(indexed.nextOffset) || 0;
    const lastHasMore = Boolean(indexed.hasMore);
    cursorStuck = nextOffset === offset;
    finalOffset = nextOffset;
    finalHasMore = lastHasMore;

    // A provider call deliberately hydrates only a bounded window. If that
    // window consists entirely of missing/peer profiles, its advancing cursor
    // is continuation work rather than an empty UI attempt. Do not spend the
    // collector's page allowance until a call yields cards (or terminates).
    if (indexedUsers.length || !lastHasMore || cursorStuck) budgetedPageCalls += 1;

    if (!lastHasMore) {
      stopReason = 'source_exhausted';
      break;
    }
    if (cursorStuck) {
      stopReason = 'cursor_not_advanced';
      break;
    }

    if (!indexedUsers.length) {
      stopReason = indexed.userIds?.length ? 'no_visible_cards_added_continue' : 'empty_index_page_continue';
      offset = nextOffset;
      continue;
    }

    offset = nextOffset;
  }

  if (pageCalls >= maxPageCalls && collected.length < requestedLimit) stopReason = 'max_page_calls_reached';
  else if (!stopReason && budgetedPageCalls >= maxPages && collected.length < requestedLimit) stopReason = 'max_pages_reached';

  return {
    collected,
    finalOffset,
    finalHasMore,
    cursorStuck,
    pageCalls,
    budgetedPageCalls,
    stale: false,
    usedIndex,
    // Індекс не дав нічого і не був використаний — читати деку доведеться
    // джерелом, інакше сторінка просто обірветься на порожньому місці.
    deferToSourcePagination: !usedIndex && collected.length === 0,
    deferReason,
    stopReason: stopReason || 'target_reached',
    indexedIdsCount,
    paginationInputIdsCount,
    pageIdsCount,
    fetchedCardsCount,
    safetyFilteredOutCount,
  };
};
