import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  RefineBar,
  RefineScroller,
  RefineKeyChip,
  RefineValueChip,
  RefineValueCount,
  RefineSummary,
  RefineKeyMenu,
  RefineKeyMenuItem,
} from './Matching.styled';
import {
  MATCHING_REFINE_KEYS,
  buildRefineOptions,
  getRefineKeySpec,
  isRefineKeyAvailableInFeed,
} from '../utils/matchingRefineKey';
import { uiText } from '../utils/uiTranslations';
import { useAppSettings } from '../hooks/useAppSettings';

/**
 * Один рядок, яким звужують довгу видачу.
 *
 * Два стани, і другий — головний хід усього візуалу:
 *
 * - **обирають** — чіп ключа плюс значення з числами. Число обовʼязкове: «31–33»
 *   саме по собі нічого не каже, а «31–33 · 74» каже і чи варто тапати, і що
 *   буде після тапу;
 * - **обрано** — рядок згортається у твердження: що увімкнено, скільки під це
 *   підпадає, скільки з того вже показано і як зняти одним тапом. Після вибору
 *   меню на екрані більше не потрібне, а місце під сіткою карток — потрібне.
 *
 * Ключ один. Другий поруч — це вже шухляда фільтрів, тож зміна ключа скидає
 * значення, а не додає ще одну умову.
 *
 * Компонент нічого не читає з бекенду й не знає, звідки взялись картки: він
 * рахує числа по тому, що йому дали. Хто дає — вирішує сторінка.
 */
export const SearchRefineBar = ({
  users = [],
  activeKey,
  activeValue,
  shownCount,
  onChangeKey,
  onSelectValue,
  keysAvailableInFeedOnly = false,
  scanNote = '',
}) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const barRef = useRef(null);

  // Меню закривається кліком повз нього — інакше воно лишалось би відкритим
  // поверх карток, і перший тап по картці витрачався б на закриття.
  useEffect(() => {
    if (!menuOpen) return undefined;
    const close = event => {
      if (barRef.current?.contains(event.target)) return;
      setMenuOpen(false);
    };
    document.addEventListener('mousedown', close);
    document.addEventListener('touchstart', close);
    return () => {
      document.removeEventListener('mousedown', close);
      document.removeEventListener('touchstart', close);
    };
  }, [menuOpen]);

  // Рядок уточнення стоїть просто під шапкою матчингу й мусить говорити тією
  // самою мовою: підпис ключа, слова-звʼязки в підсумку й підказки кнопок.
  const { language } = useAppSettings();
  const spec = getRefineKeySpec(activeKey);
  const specLabel = uiText(spec.label, language);
  const options = useMemo(() => buildRefineOptions(activeKey, users), [activeKey, users]);
  const activeOption = options.find(option => option.value === activeValue) || null;

  const selectKey = key => {
    setMenuOpen(false);
    if (key === activeKey) return;
    onChangeKey(key);
  };

  const keyMenu = menuOpen ? (
    <RefineKeyMenu role="radiogroup" aria-label={uiText('Ключ уточнення', language)}>
      {MATCHING_REFINE_KEYS.map(candidate => {
        const unavailable = keysAvailableInFeedOnly && !isRefineKeyAvailableInFeed(candidate.key);
        return (
          <RefineKeyMenuItem
            key={candidate.key}
            type="button"
            role="radio"
            aria-checked={candidate.key === activeKey}
            disabled={unavailable}
            // Ім'я пункту називає ключ, а причину недоступності несе воно ж —
            // інакше підказку `title` браузер підставляє замість імені, і
            // пункт озвучується як «У стрічці цей ключ потребує індексу».
            aria-label={unavailable
              ? uiText('{label} — потрібен індекс searchKey', language, { label: uiText(candidate.label, language) })
              : uiText(candidate.label, language)}
            title={unavailable ? uiText('У стрічці цей ключ потребує індексу searchKey', language) : uiText(candidate.label, language)}
            onClick={() => selectKey(candidate.key)}
          >
            <span aria-hidden="true" style={{ width: 12 }}>{candidate.key === activeKey ? '✓' : ''}</span>
            <span>{uiText(candidate.label, language)}</span>
            {unavailable && <small>{uiText('потрібен індекс', language)}</small>}
          </RefineKeyMenuItem>
        );
      })}
    </RefineKeyMenu>
  ) : null;

  if (activeValue) {
    const total = activeOption?.count ?? users.length;
    // Скільки знайшлося **до** уточнення. Без цього числа згорнутий рядок каже
    // «12» там, де запит дав чотириста, і різниця виглядає як загублена видача,
    // а не як власне уточнення читача.
    const overall = users.length;
    const shown = shownCount !== undefined && shownCount < total
      ? uiText('показано {shown} з {total}', language, { shown: shownCount, total })
      : `${total}${scanNote ? ` ${scanNote}` : uiText(' у видачі', language)}`;
    return (
      <RefineBar ref={barRef} data-testid="search-refine-bar">
        <RefineValueChip
          type="button"
          $active
          aria-pressed
          aria-label={uiText('Зняти уточнення {spec}: {value}', language, {
            spec: specLabel,
            value: activeOption ? uiText(activeOption.label, language) : activeValue,
          })}
          title={uiText('Зняти уточнення', language)}
          onClick={() => onSelectValue(null)}
        >
          <span>{`${specLabel} · ${activeOption ? uiText(activeOption.label, language) : activeValue}`}</span>
          <RefineValueCount>{total}</RefineValueCount>
          <span aria-hidden="true">✕</span>
        </RefineValueChip>
        <RefineSummary>
          {overall > total ? uiText('{shown} · знайдено {overall}', language, { shown, overall }) : shown}
        </RefineSummary>
      </RefineBar>
    );
  }

  return (
    <RefineBar ref={barRef} data-testid="search-refine-bar">
      <RefineScroller role="group" aria-label={uiText('Уточнити: {label}', language, { label: specLabel })}>
        <RefineKeyChip
          type="button"
          aria-expanded={menuOpen}
          aria-haspopup="true"
          title={uiText('Обрати ключ уточнення', language)}
          onClick={() => setMenuOpen(open => !open)}
        >
          <span>{specLabel}</span>
          <span aria-hidden="true">▾</span>
        </RefineKeyChip>
        {options.map(option => (
          <RefineValueChip
            key={option.value}
            type="button"
            aria-pressed={false}
            // Нульове значення гасне, а не зникає: чіп, що пропадає під пальцем,
            // смикає ряд саме тоді, коли в нього цілять.
            disabled={option.count === 0}
            title={`${specLabel}: ${uiText(option.label, language)} — ${option.count}`}
            onClick={() => onSelectValue(option.value)}
          >
            <span>{uiText(option.label, language)}</span>
            <RefineValueCount>{option.count}</RefineValueCount>
          </RefineValueChip>
        ))}
      </RefineScroller>
      {scanNote ? <RefineSummary>{scanNote}</RefineSummary> : null}
      {keyMenu}
    </RefineBar>
  );
};

export default SearchRefineBar;
